STATUS = '#!/usr/bin/env python3\n"""Penulis /marimo/llm/status.json — dipakai dashboard marimo untuk progress realtime."""\nfrom __future__ import annotations\n\nimport json\nimport os\nimport shutil\nimport subprocess\nimport time\n\nMODEL_DIR = "/home/marimo/models/sc117/IQ3_S"\nTOTAL_BYTES = 83_863_586_496          # shard1 + shard2\nPHASE_FILE = "/marimo/llm/phase"\nOUT = "/marimo/llm/status.json"\nKEY = open("/marimo/llm/api_key.txt").read().strip() if os.path.exists("/marimo/llm/api_key.txt") else ""\n\nLABEL = {\n    "start": "menyiapkan",\n    "strata": "memasang Strata",\n    "download": "mengunduh model",\n    "aux": "mengunduh runtime",\n    "prep": "menyiapkan berkas",\n    "launch": "memuat model ke GPU",\n    "relay": "menyambung ke Cloudflare",\n    "done": "selesai",\n}\n\n\ndef du(path: str) -> int:\n    total = 0\n    for root, _dirs, files in os.walk(path):\n        for f in files:\n            try:\n                total += os.path.getsize(os.path.join(root, f))\n            except OSError:\n                pass\n    return total\n\n\ndef ram_gb() -> float:\n    try:\n        with open("/proc/meminfo") as fh:\n            info = {line.split(":")[0]: int(line.split()[1]) for line in fh if ":" in line}\n        return round((info["MemTotal"] - info["MemAvailable"]) / 1024 / 1024, 1)\n    except Exception:  # noqa: BLE001\n        return 0.0\n\n\ndef vram_gb() -> float:\n    try:\n        out = subprocess.run(\n            ["nvidia-smi", "--query-gpu=memory.used", "--format=csv,noheader,nounits"],\n            capture_output=True, text=True, timeout=3).stdout.strip().splitlines()\n        return round(int(out[0]) / 1024, 1) if out else 0.0\n    except Exception:  # noqa: BLE001\n        return 0.0\n\n\ndef http_code(url: str, timeout: int = 3) -> int:\n    try:\n        out = subprocess.run(\n            ["curl", "-s", "-m", str(timeout), "-o", "/dev/null", "-w", "%{http_code}",\n             url, "-H", f"Authorization: Bearer {KEY}"],\n            capture_output=True, text=True, timeout=timeout + 3).stdout.strip()\n        return int(out or 0)\n    except Exception:  # noqa: BLE001\n        return 0\n\n\ndef main() -> None:\n    t0 = time.time()\n    last_bytes, last_t = 0, t0\n    speed = 0.0\n    while True:\n        try:\n            phase = open(PHASE_FILE).read().strip() or "start"\n        except OSError:\n            phase = "start"\n\n        size = du(MODEL_DIR) if phase in ("download", "aux", "prep", "launch") else TOTAL_BYTES\n        now = time.time()\n        if now - last_t >= 2:\n            inst = (size - last_bytes) / (now - last_t) / 1e6\n            speed = inst if inst >= 0 else speed\n            last_bytes, last_t = size, now\n\n        pct = 100.0 if phase in ("done",) else min(99.9, size / TOTAL_BYTES * 100)\n        eta = int((TOTAL_BYTES - size) / (speed * 1e6)) if speed > 1 and size < TOTAL_BYTES else 0\n\n        server = public = 0\n        if phase in ("launch", "relay", "done"):\n            server = http_code("http://127.0.0.1:8081/v1/models")\n        if phase in ("relay", "done"):\n            public = http_code("https://ai.wanz4bigel.dpdns.org/v1/models", 5)\n\n        state = {\n            "t": time.strftime("%H:%M:%S"),\n            "elapsed_s": int(now - t0),\n            "phase": phase,\n            "phase_label": LABEL.get(phase, phase),\n            "model_gb": round(size / 1e9, 1),\n            "total_gb": round(TOTAL_BYTES / 1e9, 1),\n            "pct": round(pct, 1),\n            "speed_mbps": round(speed, 0),\n            "eta_s": eta,\n            "ram_gb": ram_gb(),\n            "vram_gb": vram_gb(),\n            "server": server,\n            "public": public,\n        }\n        tmp = OUT + ".tmp"\n        with open(tmp, "w") as fh:\n            json.dump(state, fh)\n        os.replace(tmp, OUT)\n        time.sleep(2)\n\n\nif __name__ == "__main__":\n    main()\n'
PIPE = '#!/bin/bash\n# Rebuild Strata + relay agent. Versi 4: paralel, polling rapat, status realtime.\nset -uo pipefail\ncd /marimo/llm\nLOG=/marimo/llm/pipeline.log\nKEY=sk-strata-d71951f458683d6a913c18fb1e31e4b3\nMODEL=/home/marimo/models/sc117\nsay(){ echo "[$(date -u +%T)] $*" >> "$LOG"; }\nphase(){ echo "$1" > /marimo/llm/phase; say "fase: $1"; }\n\nmkdir -p /marimo/llm "$MODEL/IQ3_S" /marimo/llm/sc117-aux /marimo/llm/sc117-data/mtp\necho "$KEY" > /marimo/llm/api_key.txt\nsay "===== mulai ====="\nphase start\n\n# status writer (realtime)\npkill -f "[s]tatus_loop.py" 2>/dev/null\nnohup python3 /marimo/llm/status_loop.py > /marimo/llm/status.log 2>&1 &\n\nphase strata\ncurl -fsSL https://github.com/Niko1221/Strata/releases/latest/download/install.sh -o /tmp/si.sh\nenv -u PYTHONPATH -u PYTHONSAFEPATH -u VIRTUAL_ENV -u PYTHONHOME \\\n    PATH=/usr/local/bin:/usr/bin:/bin:/usr/local/sbin:/usr/sbin:/sbin \\\n    sh /tmp/si.sh >> "$LOG" 2>&1\nsay "strata rc=$?"\n\nR=SC117/Qwen3.8-Flash-Next-GSQ-RCO-abliterated-GGUF\nphase download\n# aux (1.7 GB) jalan paralel dengan unduhan utama (79 GB)\n( hf download "$R" --include "strata/rt/*" --local-dir /marimo/llm/sc117-aux \\\n    && hf download "$R" mmproj-Qwen3.8-Flash-Next-BF16.gguf --local-dir "$MODEL/IQ3_S" ) \\\n    >> "$LOG" 2>&1 &\nAUX=$!\n\nhf download "$R" --include "IQ3_S/*.gguf" --local-dir "$MODEL" >> "$LOG" 2>&1\nsay "shards rc=$? $(du -sh "$MODEL" 2>/dev/null | cut -f1)"\nphase aux\nwait $AUX\nsay "aux rc=$?"\n\nphase prep\ncp -r /marimo/llm/sc117-aux/strata/rt /marimo/llm/sc117-data/mtp/ 2>/dev/null\nsay "prep ok"\n\ncat > /marimo/llm/launch.sh <<\'EOL\'\n#!/bin/bash\ncd /marimo/llm\nS=/home/marimo/.local/share/strata/terminal/current/bin/strata\nexec env -u PYTHONPATH -u PYTHONSAFEPATH -u VIRTUAL_ENV "$S" launch \\\n  --model-path /home/marimo/models/sc117/IQ3_S --model iq3_s --family swift \\\n  --data-dir /marimo/llm/sc117-data --context 256k --vision gpu --mtp on \\\n  --kv int8 --tune skip --access local --port 8081 \\\n  --api-key sk-strata-d71951f458683d6a913c18fb1e31e4b3 --yes --no-tui\nEOL\ncat > /marimo/llm/relay.sh <<\'EOR\'\n#!/bin/bash\ncd /marimo/llm\nexport RELAY_URL=wss://ai.wanz4bigel.dpdns.org/_agent\nexport AGENT_TOKEN=agt_736811c6b67d3f956d991df748a78c3a\nif ! python3 -c "import websockets" 2>/dev/null; then\n  python3 -m pip install --quiet websockets >> /marimo/llm/relay.log 2>&1 || \\\n  uv pip install --system websockets >> /marimo/llm/relay.log 2>&1 || \\\n  pip install --quiet websockets >> /marimo/llm/relay.log 2>&1\nfi\nwhile true; do\n  python3 /marimo/llm/agent.py >> /marimo/llm/relay.log 2>&1\n  echo "[$(date -u +%T)] agent keluar, restart 5s" >> /marimo/llm/relay.log\n  sleep 5\ndone\nEOR\nchmod +x /marimo/llm/launch.sh /marimo/llm/relay.sh\n\nphase launch\nnohup bash /marimo/llm/launch.sh >> /marimo/llm/launch.log 2>&1 &\nsay "launch pid=$!"\n\ncode=000\nfor i in $(seq 1 200); do\n  code=$(curl -s -o /dev/null -w "%{http_code}" -m 2 http://127.0.0.1:8081/v1/models -H "Authorization: Bearer $KEY")\n  [ "$code" = "200" ] && break\n  sleep 2\ndone\nsay "server=$code setelah $((i*2))s"\n\nif [ "$code" = "200" ]; then\n  phase relay\n  nohup bash /marimo/llm/relay.sh >> /marimo/llm/relay.log 2>&1 &\n  for i in $(seq 1 30); do\n    pub=$(curl -s -o /dev/null -w "%{http_code}" -m 5 https://ai.wanz4bigel.dpdns.org/v1/models -H "Authorization: Bearer $KEY")\n    [ "$pub" = "200" ] && break\n    sleep 2\n  done\n  say "publik=$pub setelah $((i*2))s"\nfi\nphase done\nsay "===== SELESAI ====="\n'

import os, subprocess
open("/marimo/llm/status_loop.py", "w").write(STATUS)
open("/marimo/llm/pipeline.sh", "w").write(PIPE)
os.chmod("/marimo/llm/pipeline.sh", 0o755)
open("/marimo/llm/phase", "w").write("done")


def sh(c, t=60):
    r = subprocess.run(["bash", "-c", c], capture_output=True, text=True, timeout=t)
    return (r.stdout + r.stderr).strip()


print("status_loop.py:", len(STATUS), "byte | pipeline.sh:", len(PIPE), "byte")
print(sh("pkill -f '[s]tatus_loop.py'; nohup python3 /marimo/llm/status_loop.py > /marimo/llm/status.log 2>&1 & sleep 6; cat /marimo/llm/status.json"))
